CREATE OR REPLACE FUNCTION nexus.search_topic_scoped_384( p_query vector(384), p_topic_label text, p_collection text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 <=> p_query)::float8 FROM nexus.chunks c JOIN nexus.topic_assignments ta ON ta.tenant_id = c.tenant_id AND ta.doc_id = encode(c.chash, 'hex') JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE c.collection = p_collection AND t.collection = p_collection AND t.label = p_topic_label AND c.embedding_384 IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash) OR EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NULL)) ORDER BY c.embedding_384 <=> p_query LIMIT p_n $$;
